CREATE TABLE public.firm_members (firm_id uuid NOT NULL REFERENCES public.firm(id), user_id uuid NOT NULL, PRIMARY KEY(firm_id,user_id));
GRANT SELECT ON public.firm_members TO authenticated; GRANT ALL ON public.firm_members TO service_role;
ALTER TABLE public.firm_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY members_self ON public.firm_members FOR SELECT TO authenticated USING(user_id=auth.uid());
ALTER TABLE public.clients ADD COLUMN firm_id uuid REFERENCES public.firm(id), ADD COLUMN legal_name text NOT NULL DEFAULT '', ADD COLUMN dba text NOT NULL DEFAULT '', ADD COLUMN ein text NOT NULL DEFAULT '', ADD COLUMN entity_type text NOT NULL DEFAULT '', ADD COLUMN address text NOT NULL DEFAULT '', ADD COLUMN fiscal_year_start integer NOT NULL DEFAULT 1, ADD COLUMN accounting_method text NOT NULL DEFAULT 'accrual', ADD COLUMN base_currency text NOT NULL DEFAULT 'USD', ADD COLUMN sales_tax boolean NOT NULL DEFAULT false, ADD COLUMN closing_date date;
UPDATE public.clients SET firm_id=(SELECT id FROM public.firm ORDER BY created_at LIMIT 1), legal_name=name;
INSERT INTO public.firm_members(firm_id,user_id) SELECT f.id,r.user_id FROM public.user_roles r CROSS JOIN (SELECT id FROM public.firm ORDER BY created_at LIMIT 1) f WHERE r.role<>'client' ON CONFLICT DO NOTHING;
CREATE FUNCTION public.has_company_access(_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(auth.uid()) AND EXISTS(SELECT 1 FROM public.clients c JOIN public.firm_members m ON m.firm_id=c.firm_id WHERE c.id=_company AND m.user_id=auth.uid()) $$;
CREATE FUNCTION public.assign_client_firm() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.firm_id IS NULL THEN SELECT firm_id INTO NEW.firm_id FROM public.firm_members WHERE user_id=auth.uid() LIMIT 1; END IF; IF NEW.firm_id IS NULL THEN RAISE EXCEPTION 'Firm membership required'; END IF; IF NEW.legal_name='' THEN NEW.legal_name:=NEW.name; END IF; RETURN NEW; END $$;
CREATE TRIGGER clients_firm BEFORE INSERT ON public.clients FOR EACH ROW EXECUTE FUNCTION public.assign_client_firm();
CREATE POLICY clients_tenant ON public.clients AS RESTRICTIVE TO authenticated USING(public.has_company_access(id) OR id=public.my_client_id(auth.uid())) WITH CHECK(public.has_company_access(id));
CREATE TABLE public.client_access (client_id uuid NOT NULL REFERENCES public.clients(id), user_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending', can_upload boolean NOT NULL DEFAULT true, can_enter boolean NOT NULL DEFAULT true, approved_at timestamptz, revoked_at timestamptz, PRIMARY KEY(client_id,user_id));
GRANT SELECT ON public.client_access TO authenticated; GRANT ALL ON public.client_access TO service_role;
ALTER TABLE public.client_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY access_read ON public.client_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_company_access(client_id));
INSERT INTO public.client_access(client_id,user_id,status,approved_at) SELECT client_id,id,'approved',now() FROM public.profiles WHERE client_id IS NOT NULL;
CREATE FUNCTION public.is_company_client(_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.client_access WHERE client_id=_company AND user_id=auth.uid() AND status='approved') $$;
CREATE FUNCTION public.client_can_upload(_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_company_client(_company) AND EXISTS(SELECT 1 FROM public.client_access WHERE client_id=_company AND user_id=auth.uid() AND can_upload) $$;
CREATE FUNCTION public.client_can_enter(_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_company_client(_company) AND EXISTS(SELECT 1 FROM public.client_access WHERE client_id=_company AND user_id=auth.uid() AND can_enter) $$;
CREATE TABLE public.accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id), number text NOT NULL, name text NOT NULL, account_type text NOT NULL, detail_type text NOT NULL DEFAULT '', parent_id uuid REFERENCES public.accounts(id), description text NOT NULL DEFAULT '', tax_line text NOT NULL DEFAULT '', is_active boolean NOT NULL DEFAULT true, UNIQUE(client_id,number), CHECK(account_type IN ('bank','accounts_receivable','other_current_asset','fixed_asset','other_asset','accounts_payable','credit_card','other_current_liability','long_term_liability','equity','income','cost_of_goods_sold','expense','other_income','other_expense')));
GRANT SELECT,INSERT,UPDATE ON public.accounts TO authenticated; GRANT ALL ON public.accounts TO service_role;
ALTER TABLE public.accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY accounts_read ON public.accounts FOR SELECT TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id));
CREATE POLICY accounts_insert ON public.accounts FOR INSERT TO authenticated WITH CHECK(public.has_company_access(client_id) AND public.can_work_books(auth.uid()));
CREATE POLICY accounts_update ON public.accounts FOR UPDATE TO authenticated USING(public.has_company_access(client_id) AND public.can_work_books(auth.uid())) WITH CHECK(public.has_company_access(client_id) AND public.can_work_books(auth.uid()));
CREATE TABLE public.journal_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id), entry_number bigint NOT NULL, entry_date date NOT NULL, memo text NOT NULL DEFAULT '', source text NOT NULL DEFAULT 'manual', voided boolean NOT NULL DEFAULT false, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), override_note text, UNIQUE(client_id,entry_number));
GRANT SELECT ON public.journal_entries TO authenticated; GRANT ALL ON public.journal_entries TO service_role;
ALTER TABLE public.journal_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY entries_read ON public.journal_entries FOR SELECT TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id));
CREATE TABLE public.journal_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_id uuid NOT NULL REFERENCES public.journal_entries(id), client_id uuid NOT NULL REFERENCES public.clients(id), account_id uuid NOT NULL REFERENCES public.accounts(id), debit_cents bigint NOT NULL DEFAULT 0, credit_cents bigint NOT NULL DEFAULT 0, description text NOT NULL DEFAULT '', contact_id uuid, CHECK(debit_cents>=0 AND credit_cents>=0 AND ((debit_cents>0 AND credit_cents=0) OR (credit_cents>0 AND debit_cents=0))));
GRANT SELECT ON public.journal_lines TO authenticated; GRANT ALL ON public.journal_lines TO service_role;
ALTER TABLE public.journal_lines ENABLE ROW LEVEL SECURITY;
CREATE POLICY lines_read ON public.journal_lines FOR SELECT TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id));
CREATE TABLE public.contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id), kind text NOT NULL, name text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', tin text NOT NULL DEFAULT '', is_1099 boolean NOT NULL DEFAULT false, w9_on_file boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, CHECK(kind IN ('customer','vendor')));
GRANT SELECT,INSERT,UPDATE ON public.contacts TO authenticated; GRANT ALL ON public.contacts TO service_role;
ALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_read ON public.contacts FOR SELECT TO authenticated USING(public.has_company_access(client_id));
CREATE POLICY contacts_insert ON public.contacts FOR INSERT TO authenticated WITH CHECK(public.has_company_access(client_id) AND public.can_work_books(auth.uid()));
CREATE POLICY contacts_update ON public.contacts FOR UPDATE TO authenticated USING(public.has_company_access(client_id) AND public.can_work_books(auth.uid())) WITH CHECK(public.has_company_access(client_id));
CREATE TABLE public.audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id), table_name text NOT NULL, row_id uuid NOT NULL, action text NOT NULL, old_data jsonb, new_data jsonb, user_id uuid, at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_log TO authenticated; GRANT ALL ON public.audit_log TO service_role;
ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON public.audit_log FOR SELECT TO authenticated USING(public.has_company_access(client_id));
CREATE FUNCTION public.book_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o jsonb; n jsonb; c uuid; r uuid; BEGIN IF TG_OP<>'INSERT' THEN o:=to_jsonb(OLD); END IF; IF TG_OP<>'DELETE' THEN n:=to_jsonb(NEW); END IF; c:=COALESCE((n->>'client_id')::uuid,(o->>'client_id')::uuid); r:=COALESCE((n->>'id')::uuid,(o->>'id')::uuid); IF TG_TABLE_NAME='clients' THEN c:=r; END IF; IF TG_TABLE_NAME='documents' THEN n:=n-'file_bytes'-'preview_bytes'; o:=o-'file_bytes'-'preview_bytes'; END IF; INSERT INTO public.audit_log(client_id,table_name,row_id,action,old_data,new_data,user_id) VALUES(c,TG_TABLE_NAME,r,TG_OP,o,n,auth.uid()); RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER accounts_audit AFTER INSERT OR UPDATE ON public.accounts FOR EACH ROW EXECUTE FUNCTION public.book_audit();
CREATE TRIGGER contacts_audit AFTER INSERT OR UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION public.book_audit();
CREATE TRIGGER entries_audit AFTER INSERT OR UPDATE ON public.journal_entries FOR EACH ROW EXECUTE FUNCTION public.book_audit();
CREATE TRIGGER lines_audit AFTER INSERT ON public.journal_lines FOR EACH ROW EXECUTE FUNCTION public.book_audit();
CREATE TRIGGER clients_audit AFTER UPDATE ON public.clients FOR EACH ROW EXECUTE FUNCTION public.book_audit();
CREATE FUNCTION public.seed_chart(_company uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE industry text; BEGIN IF auth.uid() IS NOT NULL AND (NOT public.has_company_access(_company) OR NOT public.can_work_books(auth.uid())) THEN RAISE EXCEPTION 'Not allowed'; END IF; SELECT lower(c.industry) INTO industry FROM public.clients c WHERE id=_company; INSERT INTO public.accounts(client_id,number,name,account_type,tax_line) SELECT _company,v.n,v.name,v.t,v.tax FROM (VALUES ('1000','Checking','bank',''),('1010','Savings','bank',''),('1100','Accounts receivable','accounts_receivable',''),('1200','Inventory','other_current_asset',''),('1300','Prepaid expenses','other_current_asset',''),('1500','Equipment','fixed_asset',''),('1600','Other assets','other_asset',''),('2000','Accounts payable','accounts_payable',''),('2100','Credit card','credit_card',''),('2200','Sales tax payable','other_current_liability',''),('2500','Long-term loans','long_term_liability',''),('3000','Owner equity','equity',''),('3100','Retained earnings','equity',''),('3200','Owner distributions','equity',''),('4000','Sales revenue','income',''),('4100','Service revenue','income',''),('5000','Cost of goods sold','cost_of_goods_sold','Sch C L42'),('6000','Advertising','expense','Sch C L8'),('6010','Bank fees','expense','Sch C L27a'),('6020','Contract labor','expense','Sch C L11'),('6030','Insurance','expense','Sch C L15'),('6040','Office expenses','expense','Sch C L18'),('6050','Rent','expense','Sch C L20b'),('6060','Repairs','expense','Sch C L21'),('6070','Supplies','expense','Sch C L22'),('6080','Utilities','expense','Sch C L25'),('6090','Wages','expense','Sch C L26'),('6100','Professional fees','expense','Sch C L17'),('7000','Interest income','other_income',''),('8000','Other expenses','other_expense','')) v(n,name,t,tax) ON CONFLICT(client_id,number) DO NOTHING; INSERT INTO public.accounts(client_id,number,name,account_type) VALUES(_company,'4200',CASE WHEN industry LIKE '%transport%' OR industry LIKE '%logistic%' THEN 'Freight revenue' WHEN industry LIKE '%salon%' OR industry LIKE '%beauty%' THEN 'Salon services' WHEN industry LIKE '%restaurant%' THEN 'Food and beverage sales' WHEN industry LIKE '%retail%' THEN 'Retail sales' WHEN industry LIKE '%nonprofit%' THEN 'Contributions' ELSE 'Consulting revenue' END,'income'),(_company,'6200',CASE WHEN industry LIKE '%transport%' OR industry LIKE '%logistic%' THEN 'Fuel' WHEN industry LIKE '%salon%' OR industry LIKE '%beauty%' THEN 'Beauty supplies' WHEN industry LIKE '%restaurant%' THEN 'Food purchases' WHEN industry LIKE '%retail%' THEN 'Merchandise purchases' WHEN industry LIKE '%nonprofit%' THEN 'Program expenses' ELSE 'Software subscriptions' END,'expense') ON CONFLICT(client_id,number) DO NOTHING; IF industry LIKE '%transport%' OR industry LIKE '%logistic%' THEN INSERT INTO public.accounts(client_id,number,name,account_type) VALUES(_company,'6210','Driver pay','expense'),(_company,'6220','Tolls','expense'),(_company,'6230','IFTA','expense') ON CONFLICT(client_id,number) DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public.seed_chart(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.seed_chart(uuid) TO authenticated,service_role;
DO $$ DECLARE c record; BEGIN FOR c IN SELECT id FROM public.clients LOOP PERFORM public.seed_chart(c.id); END LOOP; END $$;
ALTER TABLE public.transactions ADD COLUMN amount_cents bigint NOT NULL DEFAULT 0, ADD COLUMN category_account_id uuid REFERENCES public.accounts(id), ADD COLUMN bank_account_id uuid REFERENCES public.accounts(id), ADD COLUMN entry_id uuid REFERENCES public.journal_entries(id), ADD COLUMN source text NOT NULL DEFAULT 'manual', ADD COLUMN deleted_at timestamptz;
UPDATE public.transactions SET amount_cents=round(amount*100)::bigint, source=CASE WHEN document_id IS NOT NULL THEN 'import' ELSE 'manual' END;
COMMENT ON COLUMN public.transactions.amount IS 'DEPRECATED: compatibility mirror of canonical integer amount_cents';
CREATE FUNCTION public.post_journal_entry(_company uuid,_date date,_memo text,_lines jsonb,_override_note text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e uuid; n bigint; l jsonb; d bigint; c bigint; td bigint:=0; tc bigint:=0; closed date; BEGIN IF NOT public.has_company_access(_company) OR NOT public.can_work_books(auth.uid()) THEN RAISE EXCEPTION 'Not allowed to post books'; END IF; IF jsonb_typeof(_lines)<>'array' OR jsonb_array_length(_lines)<2 THEN RAISE EXCEPTION 'At least two lines required'; END IF; SELECT closing_date INTO closed FROM public.clients WHERE id=_company FOR UPDATE; IF _date IS NULL THEN RAISE EXCEPTION 'Date required'; END IF; IF _date<=closed AND NULLIF(trim(_override_note),'') IS NULL THEN RAISE EXCEPTION 'Closed period: an override note is required'; END IF; FOR l IN SELECT value FROM jsonb_array_elements(_lines) LOOP IF COALESCE(l->>'debit_cents','0') !~ '^\d+$' OR COALESCE(l->>'credit_cents','0') !~ '^\d+$' THEN RAISE EXCEPTION 'Amounts must be integer cents'; END IF; d:=COALESCE((l->>'debit_cents')::bigint,0); c:=COALESCE((l->>'credit_cents')::bigint,0); IF d<0 OR c<0 OR (d=0 AND c=0) OR (d>0 AND c>0) THEN RAISE EXCEPTION 'Each line requires exactly one positive debit or credit'; END IF; IF NOT EXISTS(SELECT 1 FROM public.accounts WHERE id=(l->>'account_id')::uuid AND client_id=_company AND is_active) THEN RAISE EXCEPTION 'Invalid or inactive account'; END IF; td:=td+d; tc:=tc+c; END LOOP; IF td<>tc THEN RAISE EXCEPTION 'Journal entry must balance'; END IF; SELECT COALESCE(max(entry_number),0)+1 INTO n FROM public.journal_entries WHERE client_id=_company; INSERT INTO public.journal_entries(client_id,entry_number,entry_date,memo,created_by,override_note) VALUES(_company,n,_date,COALESCE(_memo,''),auth.uid(),NULLIF(trim(_override_note),'')) RETURNING id INTO e; FOR l IN SELECT value FROM jsonb_array_elements(_lines) LOOP INSERT INTO public.journal_lines(entry_id,client_id,account_id,debit_cents,credit_cents,description,contact_id) VALUES(e,_company,(l->>'account_id')::uuid,COALESCE((l->>'debit_cents')::bigint,0),COALESCE((l->>'credit_cents')::bigint,0),COALESCE(l->>'description',''),NULLIF(l->>'contact_id','')::uuid); END LOOP; RETURN e; END $$;
REVOKE ALL ON FUNCTION public.post_journal_entry(uuid,date,text,jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.post_journal_entry(uuid,date,text,jsonb,text) TO authenticated;
CREATE FUNCTION public.void_journal_entry(_entry uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; dt date; closed date; BEGIN SELECT client_id,entry_date INTO c,dt FROM public.journal_entries WHERE id=_entry FOR UPDATE; IF c IS NULL OR NOT public.has_company_access(c) OR NOT public.can_work_books(auth.uid()) THEN RAISE EXCEPTION 'Not allowed'; END IF; SELECT closing_date INTO closed FROM public.clients WHERE id=c; IF dt<=closed THEN RAISE EXCEPTION 'Cannot void an entry in a closed period'; END IF; UPDATE public.journal_entries SET voided=true WHERE id=_entry; END $$;
REVOKE ALL ON FUNCTION public.void_journal_entry(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.void_journal_entry(uuid) TO authenticated;
CREATE FUNCTION public.transaction_books_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ls jsonb; BEGIN IF TG_OP='INSERT' THEN IF NEW.amount_cents=0 AND NEW.amount<>0 THEN NEW.amount_cents:=round(NEW.amount*100)::bigint; END IF; ELSIF NEW.amount IS DISTINCT FROM OLD.amount AND NEW.amount_cents=OLD.amount_cents THEN NEW.amount_cents:=round(NEW.amount*100)::bigint; END IF; IF NEW.amount_cents<0 THEN RAISE EXCEPTION 'Amount must be positive'; END IF; NEW.amount:=NEW.amount_cents::numeric/100; NEW.updated_at:=now(); IF NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status<>'posted' OR NEW.amount_cents IS DISTINCT FROM OLD.amount_cents OR NEW.category_account_id IS DISTINCT FROM OLD.category_account_id OR NEW.bank_account_id IS DISTINCT FROM OLD.bank_account_id OR NEW.txn_date IS DISTINCT FROM OLD.txn_date OR NEW.direction IS DISTINCT FROM OLD.direction) THEN IF NEW.category_account_id IS NULL OR NEW.bank_account_id IS NULL OR NEW.category_account_id=NEW.bank_account_id THEN RAISE EXCEPTION 'Choose a category account and a different bank account before recording'; END IF; IF NOT EXISTS(SELECT 1 FROM public.accounts WHERE id=NEW.bank_account_id AND client_id=NEW.client_id AND account_type IN ('bank','credit_card')) THEN RAISE EXCEPTION 'Choose a bank or credit card account'; END IF; IF TG_OP='UPDATE' AND OLD.entry_id IS NOT NULL THEN PERFORM public.void_journal_entry(OLD.entry_id); END IF; ls:=jsonb_build_array(jsonb_build_object('account_id',CASE WHEN NEW.direction='in' THEN NEW.bank_account_id ELSE NEW.category_account_id END,'debit_cents',NEW.amount_cents,'credit_cents',0),jsonb_build_object('account_id',CASE WHEN NEW.direction='in' THEN NEW.category_account_id ELSE NEW.bank_account_id END,'credit_cents',NEW.amount_cents,'debit_cents',0)); NEW.entry_id:=public.post_journal_entry(NEW.client_id,NEW.txn_date,NEW.description,ls,NULL); SELECT name INTO NEW.account FROM public.accounts WHERE id=NEW.category_account_id; NEW.category:=NEW.account; END IF; IF TG_OP='UPDATE' AND OLD.status='posted' AND NEW.status<>'posted' THEN RAISE EXCEPTION 'Posted entries cannot be returned to draft'; END IF; IF TG_OP='UPDATE' AND NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL AND OLD.entry_id IS NOT NULL THEN PERFORM public.void_journal_entry(OLD.entry_id); END IF; RETURN NEW; END $$;
CREATE TRIGGER transactions_books BEFORE INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.transaction_books_guard();
CREATE TRIGGER transactions_audit AFTER INSERT OR UPDATE OR DELETE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.book_audit();
CREATE FUNCTION public.categorize_transaction(_txn uuid,_category uuid,_bank uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; e uuid; BEGIN SELECT client_id INTO c FROM public.transactions WHERE id=_txn AND deleted_at IS NULL FOR UPDATE; IF NOT public.has_company_access(c) OR NOT public.can_work_books(auth.uid()) THEN RAISE EXCEPTION 'Not allowed'; END IF; UPDATE public.transactions SET category_account_id=_category,bank_account_id=_bank,status='posted' WHERE id=_txn RETURNING entry_id INTO e; RETURN e; END $$;
REVOKE ALL ON FUNCTION public.categorize_transaction(uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.categorize_transaction(uuid,uuid,uuid) TO authenticated;
CREATE FUNCTION public.delete_transaction(_txn uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.transactions; BEGIN SELECT * INTO t FROM public.transactions WHERE id=_txn FOR UPDATE; IF NOT (public.has_company_access(t.client_id) AND public.can_work_books(auth.uid())) AND NOT (public.client_can_enter(t.client_id) AND t.created_by=auth.uid() AND t.status='draft' AND t.source='client') THEN RAISE EXCEPTION 'Not allowed'; END IF; UPDATE public.transactions SET deleted_at=now() WHERE id=_txn; END $$;
REVOKE ALL ON FUNCTION public.delete_transaction(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.delete_transaction(uuid) TO authenticated;
CREATE POLICY txns_client_insert ON public.transactions FOR INSERT TO authenticated WITH CHECK(public.client_can_enter(client_id) AND created_by=auth.uid() AND source='client' AND status='draft' AND entry_id IS NULL);
CREATE POLICY txns_client_own ON public.transactions FOR SELECT TO authenticated USING(public.is_company_client(client_id) AND created_by=auth.uid() AND source='client');
CREATE POLICY txns_client_update ON public.transactions FOR UPDATE TO authenticated USING(public.client_can_enter(client_id) AND created_by=auth.uid() AND source='client' AND status='draft') WITH CHECK(public.client_can_enter(client_id) AND created_by=auth.uid() AND source='client' AND status='draft' AND entry_id IS NULL);
CREATE POLICY txns_tenant ON public.transactions AS RESTRICTIVE TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id)) WITH CHECK(public.has_company_access(client_id) OR public.is_company_client(client_id));
CREATE TABLE public.doc_folders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL REFERENCES public.clients(id),name text NOT NULL,parent_id uuid REFERENCES public.doc_folders(id),created_by uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.doc_folders TO authenticated; GRANT ALL ON public.doc_folders TO service_role;
ALTER TABLE public.doc_folders ENABLE ROW LEVEL SECURITY;
CREATE POLICY folders_read ON public.doc_folders FOR SELECT TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id));
CREATE POLICY folders_write ON public.doc_folders FOR ALL TO authenticated USING(public.has_company_access(client_id) AND public.can_work_books(auth.uid())) WITH CHECK(public.has_company_access(client_id) AND public.can_work_books(auth.uid()));
ALTER TABLE public.documents ADD COLUMN folder_id uuid REFERENCES public.doc_folders(id),ADD COLUMN deleted_at timestamptz;
CREATE POLICY docs_client_edit ON public.documents FOR UPDATE TO authenticated USING(public.client_can_upload(client_id) AND uploaded_by=auth.uid()) WITH CHECK(public.client_can_upload(client_id) AND uploaded_by=auth.uid());
CREATE POLICY docs_tenant ON public.documents AS RESTRICTIVE TO authenticated USING(public.has_company_access(client_id) OR public.is_company_client(client_id)) WITH CHECK(public.has_company_access(client_id) OR public.client_can_upload(client_id));
CREATE TRIGGER documents_audit AFTER INSERT OR UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.book_audit();
CREATE FUNCTION public.document_client_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_company_access(OLD.client_id) AND (NEW.client_id IS DISTINCT FROM OLD.client_id OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by OR NEW.file_bytes IS DISTINCT FROM OLD.file_bytes OR NEW.status IS DISTINCT FROM OLD.status OR NEW.parse_status IS DISTINCT FROM OLD.parse_status OR NEW.request_id IS DISTINCT FROM OLD.request_id) THEN RAISE EXCEPTION 'Only document names and folders can be edited'; END IF; IF NEW.folder_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.doc_folders WHERE id=NEW.folder_id AND client_id=NEW.client_id) THEN RAISE EXCEPTION 'Invalid folder'; END IF; RETURN NEW; END $$;
CREATE TRIGGER documents_client_guard BEFORE UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.document_client_guard();
CREATE TABLE public.client_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL REFERENCES public.clients(id),email text,token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),status text NOT NULL DEFAULT 'active',expires_at timestamptz NOT NULL DEFAULT(now()+interval '30 days'),used_by uuid,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.client_invites TO authenticated; GRANT ALL ON public.client_invites TO service_role;
ALTER TABLE public.client_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invites_read ON public.client_invites FOR SELECT TO authenticated USING(public.has_company_access(client_id) AND public.is_firm_admin(auth.uid()));
CREATE POLICY invites_insert ON public.client_invites FOR INSERT TO authenticated WITH CHECK(public.has_company_access(client_id) AND public.is_firm_admin(auth.uid()) AND status='active' AND expires_at<=now()+interval '30 days');
CREATE POLICY invites_update ON public.client_invites FOR UPDATE TO authenticated USING(public.has_company_access(client_id) AND public.is_firm_admin(auth.uid()));
CREATE FUNCTION public.claim_client_invite(_token uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.client_invites; mail text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT * INTO i FROM public.client_invites WHERE token=_token FOR UPDATE; IF i.used_by=auth.uid() THEN RETURN i.client_id; END IF; IF i.id IS NULL OR i.status<>'active' OR i.expires_at<=now() THEN RAISE EXCEPTION 'Invitation is expired or unavailable'; END IF; mail:=auth.jwt()->>'email'; IF i.email IS NOT NULL AND lower(i.email)<>lower(mail) THEN RAISE EXCEPTION 'This invitation belongs to another email'; END IF; IF public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Use a client account'; END IF; INSERT INTO public.client_access(client_id,user_id) VALUES(i.client_id,auth.uid()) ON CONFLICT DO NOTHING; UPDATE public.profiles SET client_id=i.client_id WHERE id=auth.uid(); UPDATE public.client_invites SET status='used',used_by=auth.uid(),used_at=now() WHERE id=i.id; RETURN i.client_id; END $$;
REVOKE ALL ON FUNCTION public.claim_client_invite(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.claim_client_invite(uuid) TO authenticated;
CREATE FUNCTION public.set_client_access(_company uuid,_user uuid,_status text,_upload boolean,_enter boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_company_access(_company) OR NOT public.is_firm_admin(auth.uid()) OR _status NOT IN ('approved','pending','revoked') THEN RAISE EXCEPTION 'Not allowed'; END IF; UPDATE public.client_access SET status=_status,can_upload=_upload,can_enter=_enter,approved_at=CASE WHEN _status='approved' THEN now() ELSE approved_at END,revoked_at=CASE WHEN _status='revoked' THEN now() ELSE NULL END WHERE client_id=_company AND user_id=_user; END $$;
REVOKE ALL ON FUNCTION public.set_client_access(uuid,uuid,text,boolean,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_client_access(uuid,uuid,text,boolean,boolean) TO authenticated;
CREATE FUNCTION public.journal_balance_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE e uuid; d numeric; c numeric; n integer; BEGIN e:=NEW.entry_id; SELECT sum(debit_cents),sum(credit_cents),count(*) INTO d,c,n FROM public.journal_lines WHERE entry_id=e; IF n<2 OR d<>c THEN RAISE EXCEPTION 'Journal entry must balance'; END IF; IF EXISTS(SELECT 1 FROM public.journal_lines l JOIN public.journal_entries j ON j.id=l.entry_id JOIN public.accounts a ON a.id=l.account_id WHERE l.entry_id=e AND (l.client_id<>j.client_id OR a.client_id<>j.client_id)) THEN RAISE EXCEPTION 'Journal account belongs to another company'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER journal_balance AFTER INSERT OR UPDATE ON public.journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.journal_balance_guard();
CREATE INDEX journal_company_date ON public.journal_entries(client_id,entry_date); CREATE INDEX lines_entry ON public.journal_lines(entry_id); CREATE INDEX audit_company_at ON public.audit_log(client_id,at DESC);